from PIL import Image

from src.ocr import parse_total, parse_currency_totals, extract_totals, extract_currency_totals


def _blank_image(name):
    path = os.path.join(tempfile.gettempdir(), name)
    Image.new("RGB", (200, 80), color="white").save(path)
    return path


def test_parse_total_basic():
    assert parse_total("Total: $128.50") == 128.50


def test_parse_total_amount_due_label():
    assert parse_total("Amount Due: $42.00") == 42.00


def test_parse_total_lowercase_label():
    assert parse_total("total: $9.99") == 9.99


def test_parse_total_thousands_separator():
    assert parse_total("Total: $1,204.75") == 1204.75


def test_parse_total_no_match_returns_none():
    assert parse_total("Thank you for your business") is None


def test_parse_total_ignores_integer_amounts():
    assert parse_total("Total: $500") is None


def test_parse_currency_totals_single_currency():
    assert parse_currency_totals("USD: $10.00", ["USD"]) == {"USD": 10.00}


def test_parse_currency_totals_multiple_currencies():
    text = "USD: $10.00 EUR: $9.20"
    assert parse_currency_totals(text, ["USD", "EUR"]) == {"USD": 10.00, "EUR": 9.20}


def test_parse_currency_totals_unknown_currency_ignored():
    assert parse_currency_totals("USD: $10.00", ["GBP"]) == {}


def test_parse_currency_totals_empty_text():
    assert parse_currency_totals("", ["USD"]) == {}


def test_parse_currency_totals_case_insensitive():
    assert parse_currency_totals("usd: $5.00", ["USD"]) == {"USD": 5.00}


@patch("src.ocr.extract_text")
def test_extract_totals_basic(mock_extract):
    mock_extract.return_value = "Total: $128.50"
    path = _blank_image("invoice1.png")
    result = extract_totals(path)
    assert result == 128.50


@patch("src.ocr.extract_text")
def test_extract_totals_low_contrast(mock_extract):
    mock_extract.return_value = "Total: $99.99"
    path = _blank_image("invoice2.png")
    result = extract_totals(path)
    assert result == 99.99


@patch("src.ocr.extract_text")
def test_extract_totals_multi_currency(mock_extract):
    mock_extract.return_value = "USD: $100.00 EUR: $85.50 GBP: $75.25"
    path = _blank_image("invoice3.png")
    result = extract_currency_totals(path, ["USD", "EUR", "GBP"])
    assert result == {"USD": 100.00, "EUR": 85.50, "GBP": 75.25}

