import re

import requests

NOMINATIM_URL = "https://nominatim.openstreetmap.org/search"

ZIP_PATTERN = re.compile(r"\b\d{5}(?:-\d{4})?\b")


def normalize_address(address):
    return " ".join(address.strip().split())


def extract_zip(address):
    match = ZIP_PATTERN.search(address)
    return match.group(0) if match else None


def geocode(address):
    query = normalize_address(address)
    if not query:
        # Nothing to look up; avoid a pointless network round-trip.
        return None
    params = {"q": query, "format": "json", "limit": 1}
    response = requests.get(NOMINATIM_URL, params=params, timeout=5)
    response.raise_for_status()
    results = response.json()
    if not results:
        return None
    return float(results[0]["lat"]), float(results[0]["lon"])


def geocode_batch(addresses):
    return [geocode(a) for a in addresses]

import pytest

from src import geocode as geocode_module
from src.geocode import normalize_address, extract_zip, geocode


class _FakeResponse:
    def __init__(self, payload):
        self._payload = payload

    def raise_for_status(self):
        pass

    def json(self):
        return self._payload


@pytest.fixture
def fake_nominatim(monkeypatch):
    """Stub out requests.get so tests never hit the real network.

    Returns a dict the test can inspect to see what was requested.
    """
    calls = {"count": 0, "params": None}

    # Canned results keyed by normalized query string.
    canned = {
        "1600 Amphitheatre Parkway, Mountain View, CA": [
            {"lat": "37.4224764", "lon": "-122.0842499"}
        ],
        "Springfield, IL": [{"lat": "39.7817213", "lon": "-89.6501481"}],
    }

    def fake_get(url, params=None, timeout=None):
        calls["count"] += 1
        calls["params"] = params
        assert url == geocode_module.NOMINATIM_URL
        return _FakeResponse(canned.get(params["q"], []))

    monkeypatch.setattr(geocode_module.requests, "get", fake_get)
    return calls


def test_normalize_address_collapses_whitespace():
    assert normalize_address("123   Main St") == "123 Main St"


def test_normalize_address_strips_edges():
    assert normalize_address("  123 Main St  ") == "123 Main St"


def test_normalize_address_idempotent():
    addr = normalize_address("123 Main St, Springfield")
    assert normalize_address(addr) == addr


def test_extract_zip_basic():
    assert extract_zip("123 Main St, Springfield, IL 62704") == "62704"


def test_extract_zip_zip_plus_four():
    assert extract_zip("123 Main St, Springfield, IL 62704-1234") == "62704-1234"


def test_extract_zip_missing_returns_none():
    assert extract_zip("123 Main St, Springfield, IL") is None


def test_extract_zip_ignores_non_zip_digits():
    assert extract_zip("Suite 4, 123 Main St, IL 62704") == "62704"


def test_geocode_full_address(fake_nominatim):
    result = geocode("1600 Amphitheatre Parkway, Mountain View, CA")
    assert result == (37.4224764, -122.0842499)
    assert fake_nominatim["params"]["format"] == "json"
    assert fake_nominatim["params"]["limit"] == 1


def test_geocode_partial_address(fake_nominatim):
    result = geocode("Springfield, IL")
    assert result == (39.7817213, -89.6501481)


def test_geocode_normalizes_before_querying(fake_nominatim):
    geocode("  Springfield,   IL ")
    assert fake_nominatim["params"]["q"] == "Springfield, IL"


def test_geocode_no_results_returns_none(fake_nominatim):
    assert geocode("Nowhere That Exists, ZZ") is None
    assert fake_nominatim["count"] == 1


def test_geocode_invalid_address(fake_nominatim):
    result = geocode("")
    assert result is None
    # Empty input should not trigger a network request at all.
    assert fake_nominatim["count"] == 0

